import{_ as p,a0 as l,w as r,s as d,I as i,x as e,a1 as n,A as a,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"將 VoIP 電話直接連接到 Asterisk 服務器 | LCTT x X-CMD","titleTemplate":false,"description":"將 VoIP 電話直接連接到 Asterisk 服務器 | LCTT (201903) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"將 VoIP 電話直接連接到 Asterisk 服務器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"將 VoIP 電話直接連接到 Asterisk 服務器 | LCTT (201903) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201903/20190228 Connecting a VoIP phone directly to an Asterisk server","title":"將 VoIP 電話直接連接到 Asterisk 服務器","tag":"201903","desc":""},"relativePath":"201903/20190228 Connecting a VoIP phone directly to an Asterisk server.md","filePath":"[post].md"}'),k={name:"201903/20190228 Connecting a VoIP phone directly to an Asterisk server.md"};function g(u,s,h,f,b,c){const t=l("Link");return r(),d("div",null,[s[21]||(s[21]=i("h1",{id:"將-voip-電話直接連接到-asterisk-服務器",tabindex:"-1"},[e("將 VoIP 電話直接連接到 Asterisk 服務器 "),i("a",{class:"header-anchor",href:"#將-voip-電話直接連接到-asterisk-服務器","aria-label":"Permalink to “將 VoIP 電話直接連接到 Asterisk 服務器”"},"​")],-1)),i("p",null,[s[1]||(s[1]=e("在我的 ",-1)),n(t,{href:"https://www.asterisk.org/"},{default:a(()=>[...s[0]||(s[0]=[e("Asterisk",-1)])]),_:1}),s[2]||(s[2]=e(" 服務器上正好有張以太網卡。由於我只用了其中一個，因此我決定將我的 VoIP 電話從本地網絡交換機換成連接到 Asterisk 服務器。",-1))]),s[22]||(s[22]=o(`<p>主要的好處是這台運行着未知質量的專有軟件的電話，在我的一般家庭網絡中不能用了。最重要的是，它不再能訪問互聯網，因此無需手動配置防火牆。</p><p>以下是我配置的方式。</p><h3 id="私有網絡配置" tabindex="-1">私有網絡配置 <a class="header-anchor" href="#私有網絡配置" aria-label="Permalink to “私有網絡配置”">​</a></h3><p>在服務器上，我在 <code>/etc/network/interfaces</code> 中給第二塊網卡分配了一個靜態 IP：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>auto eth1</span></span>
<span class="line"><span>iface eth1 inet static</span></span>
<span class="line"><span>    address 192.168.2.2</span></span>
<span class="line"><span>    netmask 255.255.255.0</span></span></code></pre></div><p>在 VoIP 電話上，我將靜態 IP 設置成 <code>192.168.2.3</code>，DNS 服務器設置成 <code>192.168.2.2</code>。我接着將 SIP 註冊 IP 地址設置成 <code>192.168.2.2</code>。</p>`,6)),i("p",null,[s[4]||(s[4]=e("DNS 服務器實際上是一個在 Asterisk 服務器上運行的 ",-1)),n(t,{href:"https://feeding.cloud.geek.nz/posts/setting-up-your-own-dnssec-aware/"},{default:a(()=>[...s[3]||(s[3]=[e("unbound 守護進程",-1)])]),_:1}),s[5]||(s[5]=e("。我唯一需要更改的配置是監聽第二張網卡，並允許 VoIP 電話進入：",-1))]),s[23]||(s[23]=o(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>server:</span></span>
<span class="line"><span>    interface: 127.0.0.1</span></span>
<span class="line"><span>    interface: 192.168.2.2</span></span>
<span class="line"><span>    access-control: 0.0.0.0/0 refuse</span></span>
<span class="line"><span>    access-control: 127.0.0.1/32 allow</span></span>
<span class="line"><span>    access-control: 192.168.2.3/32 allow</span></span></code></pre></div><p>最後，我在 <code>/etc/network/iptables.up.rules</code> 中打開了服務器防火牆上的正確端口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-A INPUT -s 192.168.2.3/32 -p udp --dport 5060 -j ACCEPT</span></span>
<span class="line"><span>-A INPUT -s 192.168.2.3/32 -p udp --dport 10000:20000 -j ACCEPT</span></span></code></pre></div><h3 id="訪問管理頁面" tabindex="-1">訪問管理頁面 <a class="header-anchor" href="#訪問管理頁面" aria-label="Permalink to “訪問管理頁面”">​</a></h3><p>現在 VoIP 電話不能在本地網絡上用了，因此無法訪問其管理頁面。從安全的角度來看，這是一件好事，但它有點不方便。</p><p>因此，在通過 ssh 連接到 Asterisk 服務器之後，我將以下內容放在我的 <code>~/.ssh/config</code> 中以便通過 <code>http://localhost:8081</code> 訪問管理頁面：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Host asterisk</span></span>
<span class="line"><span>    LocalForward 8081 192.168.2.3:80</span></span></code></pre></div><hr>`,8)),i("p",null,[s[7]||(s[7]=e("via: ",-1)),n(t,{href:"https://feeding.cloud.geek.nz/posts/connecting-voip-phone-directly-to-asterisk-server/"},{default:a(()=>[...s[6]||(s[6]=[e("https://feeding.cloud.geek.nz/posts/connecting-voip-phone-directly-to-asterisk-server/",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=e("作者：",-1)),n(t,{href:"https://fmarier.org/"},{default:a(()=>[...s[8]||(s[8]=[e("François Marier",-1)])]),_:1}),s[13]||(s[13]=e(" 選題：",-1)),n(t,{href:"https://github.com/lujun9972"},{default:a(()=>[...s[9]||(s[9]=[e("lujun9972",-1)])]),_:1}),s[14]||(s[14]=e(" 譯者：",-1)),n(t,{href:"https://github.com/geekpi"},{default:a(()=>[...s[10]||(s[10]=[e("geekpi",-1)])]),_:1}),s[15]||(s[15]=e(" 校對：",-1)),n(t,{href:"https://github.com/wxy"},{default:a(()=>[...s[11]||(s[11]=[e("wxy",-1)])]),_:1})]),i("p",null,[s[18]||(s[18]=e("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[16]||(s[16]=[e("LCTT",-1)])]),_:1}),s[19]||(s[19]=e(" 原創編譯，",-1)),n(t,{href:"https://linux.cn/"},{default:a(()=>[...s[17]||(s[17]=[e("Linux中國",-1)])]),_:1}),s[20]||(s[20]=e(" 榮譽推出",-1))])])}const m=p(k,[["render",g]]);export{T as __pageData,m as default};
